def isAdditiveNumber(num):
    n = len(num)
    for i in range(1, n):
        if i > 1 and num[0] == "0":
            break
        for j in range(i + 1, n):
            if j - i > 1 and num[i] == "0":
                break
            x, y, pos = int(num[:i]), int(num[i:j]), j
            while pos < n:
                z = str(x + y)
                if not num.startswith(z, pos):
                    break
                pos += len(z)
                x, y = y, x + y
            if pos == n:
                return True
    return False
